/**
 * Free 计划快捷安装 / 试用入口
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import {
  PRODUCT_NAME,
  SHOPIFY_INSTALL_PAGE_PATH,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
} from '../../constants/brand';
import { useI18n } from '../../i18n';
import { trackEvent } from '../../utils/analytics';
import './free-install-cta.css';

/**
 * 🔴 本组件被**本地化页面**复用（首页 / 定价页 / 恢复邮件页），因此：
 *    ① 所有可见文案走 `common.js` 的 `freeCta` 字典 —— 不能硬编码英文，
 *       否则 /de/、/fr/ 页面会夹着一块英文按钮；
 *    ② 站内链接必须过 `localePath()`，否则德/法页面点「See Free vs Growth」
 *       会掉回英文 `/pricing/`（/install/ 同理）。本组件此前两处都没做。
 *
 * @param {object} props
 * @param {'banner'|'card'|'inline'} [props.variant]
 * @param {string} [props.title] 覆盖默认标题（调用方通常传已本地化的页内文案）
 * @param {string} [props.className]
 * @param {boolean} [props.showPricingLink]
 * @param {boolean} [props.hideActions] 安装页正文上方仅展示说明，避免再链回 /install
 * @param {string} [props.primaryTo] 主按钮目标，默认 /install/
 * @param {string} [props.primaryLabel] 覆盖主按钮文案
 */
export default function FreeInstallCta({
  variant = 'banner',
  title,
  className = '',
  showPricingLink = true,
  hideActions = false,
  primaryTo = SHOPIFY_INSTALL_PAGE_PATH,
  primaryLabel,
}) {
  const { localePath, t } = useI18n();
  const f = t.freeCta;
  const heading = title || f.defaultTitle.replace('{product}', PRODUCT_NAME);
  const primaryText = primaryLabel || f.installNow;
  const primaryIsHash = typeof primaryTo === 'string' && primaryTo.startsWith('#');

  // 🔴 归因要点：**只上报 variant（按钮位置），绝不上报 store 域名或任何可识别信息**。
  //    variant 让 GA4 能区分「首屏横幅」与「页脚卡片」的点击效果。
  const trackCta = (label) => trackEvent('cta_click', { cta_label: label, cta_variant: variant });

  return (
    <div className={`free-install-cta free-install-cta--${variant} ${className}`.trim()}>
      <div className="free-install-cta-copy">
        <span className="free-install-cta-badge">{f.badge}</span>
        <h3 className="free-install-cta-title">{heading}</h3>
        <p className="free-install-cta-lead">
          {f.leadPre}
          <strong>{f.leadStrong}</strong>
          {f.leadPost}
        </p>
      </div>
      {!hideActions && (
        <div className="free-install-cta-actions">
          {primaryIsHash ? (
            <a
              href={primaryTo}
              className="free-install-cta-btn free-install-cta-btn-primary"
              onClick={() => trackCta('install_primary')}
            >
              {primaryText}
            </a>
          ) : (
            <Link
              to={localePath(primaryTo)}
              className="free-install-cta-btn free-install-cta-btn-primary"
              onClick={() => trackCta('install_primary')}
            >
              {primaryText}
            </Link>
          )}
          <a
            href={SHOPIFY_APP_STORE_URL}
            className="free-install-cta-btn free-install-cta-btn-secondary"
            target="_blank"
            rel="noopener noreferrer"
            onClick={() => trackCta('app_store')}
          >
            {f.tryStore.replace('{store}', SHOPIFY_APP_STORE_LABEL)}
          </a>
          {showPricingLink && variant !== 'inline' && (
            <Link
              to={localePath('/pricing/')}
              className="free-install-cta-link"
              onClick={() => trackCta('pricing')}
            >
              {f.seePricing}
            </Link>
          )}
        </div>
      )}
    </div>
  );
}
